"""Generate docs/COMMANDS.md from the command and shortcut tables:
python tools/gen_command_docs.py"""
import os
import sys

sys.path.insert(0, os.path.join(os.path.dirname(__file__), ".."))
from openschematix import commands  # noqa: E402
from openschematix.gui.keymap import DEFAULT_ACTIONS, FIXED, pretty  # noqa: E402

OUT = os.path.join(os.path.dirname(__file__), "..", "docs", "COMMANDS.md")


def main():
    lines = ["# Commands and keyboard shortcuts", "",
             "_Generated by `tools/gen_command_docs.py`._", "",
             "Type a command or alias anywhere on the drawing (the letters go to the command line) and press "
             "Enter or Space. Enter or Space on an empty command line repeats the last command; Esc cancels. "
             "While a command asks for a point you can click (with grid snap, object snap and ortho) or type:",
             "", "| Input | Meaning |", "|---|---|",
             "| `100,50` | absolute point in mm; origin at the sheet's lower-left corner, Y up |",
             "| `@20,0` | relative to the last point |",
             "| `@30<45` | polar: 30 mm at 45° (counter-clockwise from +X) |",
             "| a number | distance, radius, angle or factor, depending on the prompt |",
             "| a keyword | options shown in brackets, e.g. `[Undo/Close]` (the first letter is enough) |",
             "| Enter / right-click | finish the command or accept the default `<…>` |", ""]
    cats = {}
    for c in commands.COMMANDS:
        cats.setdefault(c.category, []).append(c)
    for cat, cmds in cats.items():
        lines += [f"## {cat}", "", "| Command | Aliases | Description | Usage |", "|---|---|---|---|"]
        for c in cmds:
            lines.append(f"| `{c.name}` | {', '.join(f'`{a}`' for a in c.aliases) or '—'} | {c.summary} | "
                         f"`{c.usage}` |")
        lines.append("")
    lines += ["## Keyboard shortcuts", "", "Change them under *Help ▸ Keyboard shortcuts*. Shortcuts must use "
              "Ctrl, Alt or a function/navigation key because letters are reserved for the command line.", "",
              "| Default | Action |", "|---|---|"]
    for _a, (label, key) in DEFAULT_ACTIONS.items():
        lines.append(f"| {pretty(key)} | {label} |")
    lines += ["", "### Fixed keys", "", "| Key | Action |", "|---|---|"]
    for k, label in FIXED:
        lines.append(f"| {k} | {label} |")
    with open(OUT, "w", encoding="utf-8") as f:
        f.write("\n".join(lines) + "\n")
    print("wrote", os.path.relpath(OUT))


if __name__ == "__main__":
    main()
